import 'package:flutter/material.dart';
import 'package:flutter_slidable/flutter_slidable.dart';

class BasicSlidableExample extends StatefulWidget {
  const BasicSlidableExample({super.key});

  @override
  State<BasicSlidableExample> createState() => _BasicSlidableExampleState();
}

class _BasicSlidableExampleState extends State<BasicSlidableExample> {
  final List<String> _items = List.generate(10, (i) => '아이템 ${i + 1}');

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Slidable 기본')),
      body: ListView.builder(
        itemCount: _items.length,
        itemBuilder: (context, index) {
          final item = _items[index];
          return Slidable(
            // 오른쪽→왼쪽 스와이프 시 나타나는 액션 (끝 액션)
            endActionPane: ActionPane(
              motion: const ScrollMotion(),
              children: [
                // 편집 버튼
                SlidableAction(
                  onPressed: (context) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(content: Text('$item 편집')),
                    );
                  },
                  backgroundColor: Colors.blue,
                  foregroundColor: Colors.white,
                  icon: Icons.edit,
                  label: '편집',
                ),
                // 삭제 버튼
                SlidableAction(
                  onPressed: (context) {
                    setState(() {
                      _items.removeAt(index);
                    });
                  },
                  backgroundColor: Colors.red,
                  foregroundColor: Colors.white,
                  icon: Icons.delete,
                  label: '삭제',
                ),
              ],
            ),

            // 리스트 아이템 내용
            child: ListTile(
              leading: CircleAvatar(child: Text('${index + 1}')),
              title: Text(item),
              subtitle: const Text('왼쪽으로 스와이프해보세요'),
            ),
          );
        },
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_slidable/flutter_slidable.dart';

class MotionExample extends StatelessWidget {
  const MotionExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('모션 비교')),
      body: ListView(
        children: [
          // 1. ScrollMotion - 스크롤처럼 밀려 나옴
          _buildSlidableItem(
            title: 'ScrollMotion',
            subtitle: '액션이 스크롤되듯 나타남',
            motion: const ScrollMotion(),
          ),

          // 2. BehindMotion - 뒤에서 나타남
          _buildSlidableItem(
            title: 'BehindMotion',
            subtitle: '액션이 뒤에 숨어있다가 보임',
            motion: const BehindMotion(),
          ),

          // 3. DrawerMotion - 서랍처럼 열림
          _buildSlidableItem(
            title: 'DrawerMotion',
            subtitle: '서랍이 열리듯 나타남',
            motion: const DrawerMotion(),
          ),

          // 4. StretchMotion - 늘어남
          _buildSlidableItem(
            title: 'StretchMotion',
            subtitle: '액션이 늘어나며 나타남',
            motion: const StretchMotion(),
          ),
        ],
      ),
    );
  }

  Widget _buildSlidableItem({
    required String title,
    required String subtitle,
    required Widget motion,
  }) {
    return Slidable(
      endActionPane: ActionPane(
        motion: motion,
        children: [
          SlidableAction(
            onPressed: (_) {},
            backgroundColor: Colors.green,
            foregroundColor: Colors.white,
            icon: Icons.archive,
            label: '보관',
          ),
          SlidableAction(
            onPressed: (_) {},
            backgroundColor: Colors.blue,
            foregroundColor: Colors.white,
            icon: Icons.share,
            label: '공유',
          ),
          SlidableAction(
            onPressed: (_) {},
            backgroundColor: Colors.red,
            foregroundColor: Colors.white,
            icon: Icons.delete,
            label: '삭제',
          ),
        ],
      ),
      child: ListTile(
        title: Text(title),
        subtitle: Text(subtitle),
        trailing: const Icon(Icons.swipe_left),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_slidable/flutter_slidable.dart';

class DismissExample extends StatefulWidget {
  const DismissExample({super.key});

  @override
  State<DismissExample> createState() => _DismissExampleState();
}

class _DismissExampleState extends State<DismissExample> {
  final List<Map<String, dynamic>> _emails = List.generate(
    10,
    (i) => {
      'id': i,
      'sender': '발신자 ${i + 1}',
      'subject': '이메일 제목 ${i + 1}',
      'preview': '이메일 내용 미리보기...',
    },
  );

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Gmail 스타일')),
      body: ListView.builder(
        itemCount: _emails.length,
        itemBuilder: (context, index) {
          final email = _emails[index];
          return Slidable(
            key: ValueKey(email['id']),  // 삭제 시 필수!

            // 왼쪽→오른쪽: 보관
            startActionPane: ActionPane(
              motion: const BehindMotion(),

              // 끝까지 스와이프 시 실행될 액션
              dismissible: DismissiblePane(
                onDismissed: () {
                  setState(() {
                    _emails.removeAt(index);
                  });
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: const Text('보관됨'),
                      action: SnackBarAction(
                        label: '실행취소',
                        onPressed: () {
                          setState(() {
                            _emails.insert(index, email);
                          });
                        },
                      ),
                    ),
                  );
                },
              ),

              children: [
                SlidableAction(
                  onPressed: (context) {
                    Slidable.of(context)?.dismiss(
                      ResizeRequest(const Duration(milliseconds: 300), () {
                        setState(() {
                          _emails.removeAt(index);
                        });
                      }),
                      duration: const Duration(milliseconds: 300),
                    );
                  },
                  backgroundColor: Colors.green,
                  foregroundColor: Colors.white,
                  icon: Icons.archive,
                  label: '보관',
                ),
              ],
            ),

            // 오른쪽→왼쪽: 삭제
            endActionPane: ActionPane(
              motion: const BehindMotion(),

              dismissible: DismissiblePane(
                onDismissed: () {
                  setState(() {
                    _emails.removeAt(index);
                  });
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: const Text('삭제됨'),
                      action: SnackBarAction(
                        label: '실행취소',
                        onPressed: () {
                          setState(() {
                            _emails.insert(index, email);
                          });
                        },
                      ),
                    ),
                  );
                },
              ),

              children: [
                SlidableAction(
                  onPressed: (context) {
                    Slidable.of(context)?.dismiss(
                      ResizeRequest(const Duration(milliseconds: 300), () {
                        setState(() {
                          _emails.removeAt(index);
                        });
                      }),
                      duration: const Duration(milliseconds: 300),
                    );
                  },
                  backgroundColor: Colors.red,
                  foregroundColor: Colors.white,
                  icon: Icons.delete,
                  label: '삭제',
                ),
              ],
            ),

            child: ListTile(
              leading: CircleAvatar(
                backgroundColor: Colors.primaries[index % Colors.primaries.length],
                child: Text(email['sender'][0]),
              ),
              title: Text(email['subject']),
              subtitle: Text(email['preview']),
              trailing: const Text('오후 2:30'),
            ),
          );
        },
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_slidable/flutter_slidable.dart';

class AdvancedSlidableExample extends StatefulWidget {
  const AdvancedSlidableExample({super.key});

  @override
  State<AdvancedSlidableExample> createState() => _AdvancedSlidableExampleState();
}

class _AdvancedSlidableExampleState extends State<AdvancedSlidableExample> {
  final List<String> _items = List.generate(10, (i) => '아이템 ${i + 1}');

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('고급 Slidable'),
        actions: [
          // 모든 Slidable 닫기 버튼
          IconButton(
            icon: const Icon(Icons.close_fullscreen),
            onPressed: () {
              // SlidableAutoCloseBehavior가 활성화된 경우
              // 하나의 Slidable을 열면 다른 것들이 자동으로 닫힘
            },
            tooltip: '모두 닫기',
          ),
        ],
      ),
      body: SlidableAutoCloseBehavior(
        // 하나의 Slidable을 열면 다른 것들이 자동으로 닫힘
        child: ListView.builder(
          itemCount: _items.length,
          itemBuilder: (context, index) {
            return _buildAdvancedSlidable(index);
          },
        ),
      ),
    );
  }

  Widget _buildAdvancedSlidable(int index) {
    final item = _items[index];

    return Slidable(
      key: ValueKey(item),

      // 스와이프 범위 제한 (0.0 ~ 1.0)
      // 기본값은 액션들의 크기에 따라 자동 계산

      // 왼쪽→오른쪽 (시작 액션)
      startActionPane: ActionPane(
        motion: const DrawerMotion(),
        extentRatio: 0.25,  // 스와이프 최대 범위 (25%)

        children: [
          // 커스텀 액션 위젯
          CustomSlidableAction(
            onPressed: (context) {
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text('$item 즐겨찾기 추가')),
              );
              Slidable.of(context)?.close();  // 액션 후 닫기
            },
            backgroundColor: Colors.amber,
            foregroundColor: Colors.white,
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Icon(Icons.star),
                const SizedBox(height: 4),
                const Text('즐겨찾기', style: TextStyle(fontSize: 12)),
              ],
            ),
          ),
        ],
      ),

      // 오른쪽→왼쪽 (끝 액션)
      endActionPane: ActionPane(
        motion: const StretchMotion(),
        extentRatio: 0.5,  // 스와이프 최대 범위 (50%)

        children: [
          SlidableAction(
            onPressed: (context) async {
              // 확인 다이얼로그 표시
              final confirmed = await showDialog<bool>(
                context: context,
                builder: (context) => AlertDialog(
                  title: const Text('삭제 확인'),
                  content: Text('$item을(를) 삭제할까요?'),
                  actions: [
                    TextButton(
                      onPressed: () => Navigator.pop(context, false),
                      child: const Text('취소'),
                    ),
                    TextButton(
                      onPressed: () => Navigator.pop(context, true),
                      child: const Text('삭제'),
                    ),
                  ],
                ),
              );

              if (confirmed == true && context.mounted) {
                setState(() {
                  _items.removeAt(index);
                });
              } else if (context.mounted) {
                // 취소 시 Slidable 닫기
                Slidable.of(context)?.close();
              }
            },
            backgroundColor: Colors.red,
            foregroundColor: Colors.white,
            icon: Icons.delete,
            label: '삭제',
            autoClose: false,  // 액션 후 자동 닫기 비활성화
          ),

          SlidableAction(
            onPressed: (context) {
              // 편집 화면으로 이동
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => Scaffold(
                    appBar: AppBar(title: Text('$item 편집')),
                    body: const Center(child: Text('편집 화면')),
                  ),
                ),
              );
            },
            backgroundColor: Colors.blue,
            foregroundColor: Colors.white,
            icon: Icons.edit,
            label: '편집',
            borderRadius: const BorderRadius.horizontal(
              right: Radius.circular(12),  // 끝 액션에 둥근 모서리
            ),
          ),
        ],
      ),

      child: Card(
        margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
        child: ListTile(
          leading: CircleAvatar(
            backgroundColor: Colors.primaries[index % Colors.primaries.length],
            child: Text('${index + 1}'),
          ),
          title: Text(item),
          subtitle: const Text('좌우로 스와이프해보세요'),
          trailing: const Icon(Icons.drag_handle),
        ),
      ),
    );
  }
}

